export const dynamic = "force-static";

// Full flyer served as a raster image for link-preview crawlers.
const flyer = "";

export function GET() {
  return new Response(Buffer.from(flyer, "base64"), {
    headers: {
      "Content-Type": "image/jpeg",
      "Cache-Control": "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
    },
  });
}
